package com.minipay.adminbff;
import java.security.Principal;import java.util.List;import java.util.Map;import org.springframework.http.CacheControl;import org.springframework.http.ResponseEntity;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.security.web.server.csrf.CsrfToken;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.server.ServerWebExchange;import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v1") public class SessionController {
 @GetMapping("/session") public Mono<Session> session(Mono<Principal> p){return p.filter(Authentication.class::isInstance).cast(Authentication.class).map(Authentication::getPrincipal).filter(OidcUser.class::isInstance).cast(OidcUser.class).map(u->new Session(true,"/oauth2/authorization/minipay-admin",new Admin(u.getClaimAsString("user_id"),u.getClaimAsString("display_name"),u.getClaimAsStringList("roles")))).defaultIfEmpty(new Session(false,"/oauth2/authorization/minipay-admin",null));}
 @GetMapping("/csrf") public Mono<ResponseEntity<Map<String,String>>> csrf(ServerWebExchange e){Mono<CsrfToken> t=e.getAttribute(CsrfToken.class.getName());return t.map(v->ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Map.of("headerName",v.getHeaderName(),"parameterName",v.getParameterName(),"token",v.getToken())));}
 public record Session(boolean authenticated,String loginUrl,Admin admin){} public record Admin(String userId,String displayName,List<String> roles){}
}
